CREATE INDEX evidence_programme ON evidence(programme_id,subject_type);
CREATE INDEX programme_scope ON programmes(classification,review_status);
CREATE INDEX window_dates ON application_windows(start_date,end_date);
CREATE TABLE application_windows(id TEXT PRIMARY KEY,intake_id TEXT NOT NULL REFERENCES intakes(id),window_type TEXT NOT NULL,round_label TEXT NOT NULL,applicant_scope TEXT NOT NULL,start_date TEXT,start_status TEXT NOT NULL,end_date TEXT,end_status TEXT NOT NULL,cutoff_time TEXT,timezone TEXT,timezone_basis TEXT NOT NULL,date_precision TEXT NOT NULL,window_status TEXT NOT NULL,evidence_origin TEXT NOT NULL,evidence_note TEXT NOT NULL,notes TEXT NOT NULL,is_displayed INTEGER NOT NULL,deadline_semantics TEXT NOT NULL,semantics_review_required INTEGER NOT NULL,CHECK(start_status!='exact' OR start_date IS NOT NULL),CHECK(end_status!='exact' OR end_date IS NOT NULL),CHECK(start_date IS NULL OR end_date IS NULL OR start_date<=end_date));
CREATE TABLE duplicate_candidates(programme_id TEXT REFERENCES programmes(id),duplicate_of TEXT REFERENCES programmes(id),evidence_note TEXT,resolution TEXT NOT NULL,PRIMARY KEY(programme_id,duplicate_of));
CREATE TABLE evidence(id TEXT PRIMARY KEY,programme_id TEXT NOT NULL REFERENCES programmes(id),source_id TEXT REFERENCES sources(id),subject_type TEXT NOT NULL,subject_id TEXT NOT NULL,claim_text TEXT NOT NULL,evidence_origin TEXT NOT NULL,checked_at TEXT);
CREATE TABLE institutions(id TEXT PRIMARY KEY,name TEXT NOT NULL,country TEXT NOT NULL,UNIQUE(name,country));
CREATE TABLE intakes(id TEXT PRIMARY KEY,programme_id TEXT NOT NULL REFERENCES programmes(id),label TEXT NOT NULL,cycle TEXT,mode TEXT NOT NULL,availability_status TEXT NOT NULL);
CREATE TABLE metadata(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE programme_aliases(alias_id TEXT PRIMARY KEY REFERENCES programmes(id),canonical_id TEXT NOT NULL REFERENCES programmes(id),resolution TEXT NOT NULL,checked_at TEXT,source_id TEXT REFERENCES sources(id),evidence_note TEXT NOT NULL);
CREATE TABLE programme_records(id TEXT PRIMARY KEY,programme_id TEXT NOT NULL REFERENCES programmes(id),record_kind TEXT NOT NULL,checked_at TEXT,public_record_json TEXT NOT NULL);
CREATE TABLE programme_sources(programme_id TEXT NOT NULL REFERENCES programmes(id),source_id TEXT NOT NULL REFERENCES sources(id),PRIMARY KEY(programme_id,source_id));
CREATE TABLE programmes(id TEXT PRIMARY KEY,institution_id TEXT NOT NULL REFERENCES institutions(id),title TEXT NOT NULL,field TEXT,classification TEXT NOT NULL,latest_regional INTEGER NOT NULL,pure_maths INTEGER NOT NULL,review_status TEXT NOT NULL,checked_at TEXT,notes TEXT NOT NULL,identity_status TEXT NOT NULL,availability_status TEXT NOT NULL);
CREATE TABLE requirement_sources(requirement_id TEXT NOT NULL REFERENCES requirements(id),source_id TEXT NOT NULL REFERENCES sources(id),PRIMARY KEY(requirement_id,source_id));
CREATE TABLE requirements(id TEXT PRIMARY KEY,programme_id TEXT NOT NULL REFERENCES programmes(id),category TEXT NOT NULL,requirement_text TEXT NOT NULL,status TEXT NOT NULL,evidence_origin TEXT NOT NULL,is_displayed INTEGER NOT NULL);
CREATE TABLE research_reviews(programme_id TEXT PRIMARY KEY REFERENCES programmes(id),status TEXT NOT NULL,checked_at TEXT,notes TEXT NOT NULL);
CREATE TABLE sources(id TEXT PRIMARY KEY,url TEXT NOT NULL UNIQUE,title TEXT,checked_at TEXT,access_status TEXT);
CREATE TABLE window_sources(window_id TEXT NOT NULL REFERENCES application_windows(id),source_id TEXT NOT NULL REFERENCES sources(id),PRIMARY KEY(window_id,source_id));
CREATE VIEW date_coverage AS SELECT p.id,p.title,p.review_status,COUNT(w.id) AS application_window_count,SUM(w.start_status='exact') AS exact_starts,SUM(w.end_status='exact') AS exact_ends FROM programmes p JOIN intakes i ON i.programme_id=p.id JOIN application_windows w ON w.intake_id=i.id WHERE w.is_displayed=1 AND w.window_type='application' GROUP BY p.id;